Local Ltac pch_finish p' E' c' g' :=
  apply evt_done; unfold pch_post;
  do 16 eexists; exists p', E', c', g';
  split; [reflexivity|]; repeat match goal with |- _ /\ _ => split end; try fast_assumption; try lia.

