Local Ltac take_exitA EX TMP TMP24 PURE0 FC0 :=
  let X := fresh "EX" in let junk := fresh "junk" in let TMPj := fresh "TMPj" in
  pose proof EX as X; unfold pch_exitA_stmt in X;
  destruct (rw_cells_forget _ _ _ _ TMP) as [junk TMPj]; rewrite TMP24 in TMPj; clear TMP;
  eapply X; [ | exact PURE0 | exact FC0 | cbn; qtauto];
  unfold pch_ctx, pch_W, G_HTTP_CAT, ParserCoreCells; cbn [pc_blim_has pc_blim pc_len pc_len0 pc_skip pc_hlim pc_state pc_f]; unfold wz;
  repeat match goal with |- _ /\ _ => split end; fast_eassumption.

