Definition pch_notfound_stmt : Prop :=
  forall rax ra sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s6x
         s7 s6v s5v s4v s3v s2v s1v s0v s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (P IN E lo : Z) (c c1 : pcore) (pad7 pad2 : list byte) (p0 : Z) (bs : list byte)
    (p : Z) (e1 e2 e3 : word) (g : bool) (tmp : list cell),
  pch_ctx m m1 sp s6v s5v s4v s3v s2v s1v s0v ra P IN E lo c1 pad7 pad2 p0 bs p e1 e2 e3 g tmp ->
  pch_pure sp P IN E lo c p0 bs -> pch_fcore c c1 (Z.of_nat (length bs)) ->
  p0 <= p <= p0 + Z.of_nat (length bs) -> cells_size tmp = 24%nat ->
  evt usegs (pch_post ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7 s8 s9 s10 s11 F fc P IN E lo c pad7 pad2 p0 bs m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -96)) gp tp t0 t1 t2 (wz E) (wz P) a0 a1 a2 a3 a4 a5 a6 a7
              (wz p) (wz IN) (wz (p0 + Z.of_nat (length bs))) (wz (Z.of_nat (length bs))) s6x s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 0x3dff0) fc None m1 (seg_rom usegs)).

