(* [comment removed for export] *)
Local Ltac spec_exitA EX ra sp s7 s6 s5 s4 s3 s2 s1 s0 F fc m P IN E lo c pad7 pad2 p0 bs pv junk24 PURE0 FC :=
  let X := fresh "EX" in
  pose proof EX as X; unfold pch_exitA_stmt in X;
  lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mx _) =>
  eapply (X _ ra sp _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ s7 s6 s5 s4 s3 s2 s1 s0 _ _ _ _ _ _ _ _
            F fc m mx P IN E lo c c pad7 pad2 p0 bs pv _ _ _ _ junk24)
  end;
  [ | exact PURE0 | exact FC | cbn; qtauto ];
  unfold pch_ctx, pch_W, G_HTTP_CAT, ParserCoreCells; cbn [pc_blim_has pc_blim pc_len pc_len0 pc_skip pc_hlim pc_state pc_f]; unfold wz;
  repeat match goal with |- _ /\ _ => split end; fast_eassumption.

